import { INVALID_ARGUMENT } from "../../../errors/index.js";
function hasAnyDependents(nodes, nodeId) {
    return nodes.some((n) => n.dependsOn?.includes(nodeId));
}
export function buildGraph(nodes) {
    const adjList = new Map();
    const inDegree = new Map();
    const nodeMap = new Map();
    for (const node of nodes) {
        if (nodeMap.has(node.id)) {
            throw INVALID_ARGUMENT.create({
                detail: `Workflow graph has duplicate node ID "${node.id}"`,
            });
        }
        adjList.set(node.id, []);
        inDegree.set(node.id, 0);
        nodeMap.set(node.id, node);
    }
    for (const node of nodes) {
        const dependencies = new Set();
        for (const dep of node.dependsOn ?? []) {
            if (dependencies.has(dep)) {
                throw INVALID_ARGUMENT.create({
                    detail: `Workflow graph node "${node.id}" contains duplicate dependency "${dep}"`,
                });
            }
            dependencies.add(dep);
            const dependents = adjList.get(dep);
            if (!dependents) {
                throw INVALID_ARGUMENT.create({
                    detail: `Node "${node.id}" depends on unknown node "${dep}"`,
                });
            }
            dependents.push(node.id);
            inDegree.set(node.id, (inDegree.get(node.id) ?? 0) + 1);
        }
    }
    // Also handle implicit sequential dependencies (nodes without explicit deps)
    // If no dependencies specified (undefined), assume sequential order
    // If dependsOn is explicitly set (even to []), respect that choice
    let prevNodeId = null;
    for (const node of nodes) {
        if (!prevNodeId) {
            prevNodeId = node.id;
            continue;
        }
        if (node.dependsOn !== undefined) {
            prevNodeId = node.id;
            continue;
        }
        const currentInDegree = inDegree.get(node.id) ?? 0;
        if (currentInDegree !== 0 || hasAnyDependents(nodes, node.id)) {
            prevNodeId = node.id;
            continue;
        }
        adjList.get(prevNodeId)?.push(node.id);
        inDegree.set(node.id, currentInDegree + 1);
        prevNodeId = node.id;
    }
    return { adjList, inDegree, nodeMap };
}
export function getReadyNodes(inDegree, nodeStates) {
    const ready = [];
    for (const [nodeId, degree] of inDegree) {
        const state = nodeStates[nodeId];
        if (degree === 0 && (!state || state.status === "pending" || state.status === "failed")) {
            ready.push(nodeId);
        }
    }
    return ready;
}
export function hasCycle(nodes, adjList) {
    const visited = new Set();
    const recursionStack = new Set();
    function dfs(nodeId) {
        visited.add(nodeId);
        recursionStack.add(nodeId);
        for (const neighbor of adjList.get(nodeId) ?? []) {
            if (!visited.has(neighbor)) {
                if (dfs(neighbor))
                    return true;
                continue;
            }
            if (recursionStack.has(neighbor))
                return true;
        }
        recursionStack.delete(nodeId);
        return false;
    }
    for (const node of nodes) {
        if (!visited.has(node.id) && dfs(node.id))
            return true;
    }
    return false;
}
export function updateInDegreesForCompletedNodes(nodeStates, adjList, inDegree) {
    for (const [nodeId, state] of Object.entries(nodeStates)) {
        if (state.status !== "completed" && state.status !== "skipped")
            continue;
        for (const dependent of adjList.get(nodeId) ?? []) {
            const currentDegree = inDegree.get(dependent) ?? 0;
            if (currentDegree > 0)
                inDegree.set(dependent, currentDegree - 1);
        }
    }
}
